Below is a self‑contained **C# console application** that demonstrates:

1. **Delegates** – how to declare, instantiate and invoke them directly (both single‑cast and multi‑cast).  
2. **Events** – how to expose a delegate as an event, subscribe to it, and raise it from inside a class.

```csharp
// -------------  Delegates & Events Demo  ----------------
using System;

namespace DelegateEventDemo
{
    // 1. A plain delegate type that takes a string and returns void.
    public delegate void NotificationHandler(string message);

    // 2. A class that will raise an event.
    public class Notifier
    {
        // The event, using the delegate type declared above.
        public event NotificationHandler OnNotify;

        // Helper to raise the event safely.
        protected virtual void RaiseNotification(string msg)
        {
            // Copy the event reference to avoid race conditions.
            NotificationHandler handler = OnNotify;
            handler?.Invoke(msg);
        }

        // Some public methods that trigger the event.
        public void SendWelcome()
        {
            RaiseNotification("Welcome to the system!");
        }

        public void SendGoodbye()
        {
            RaiseNotification("Goodbye! See you soon.");
        }
    }

    class Program
    {
        static void Main()
        {
            // ----------------------------------------------------
            // 3. Using the delegate directly (no event involved)
            // ----------------------------------------------------
            // Create a single‑cast delegate instance pointing to a method.
            NotificationHandler single = MessagePrinter;

            // Invoke the delegate.
            single("This is a single‑cast delegate call.");

            // Create a multi‑cast delegate (combines two methods).
            NotificationHandler multi = MessagePrinter;
            multi += MessageLogger;

            // Invoke the multi‑cast delegate – both methods run.
            multi("This is a multi‑cast delegate call.");

            // ----------------------------------------------------
            // 4. Using events
            // ----------------------------------------------------
            var notifier = new Notifier();

            // Subscribe to the event with a method.
            notifier.OnNotify += MessagePrinter;

            // Subscribe again with a lambda expression.
            notifier.OnNotify += msg => Console.WriteLine($"[Lambda] {msg}");

            // Raise the event by calling a method on the notifier.
            notifier.SendWelcome();   // Triggers all subscribers
            notifier.SendGoodbye();

            // Unsubscribe one handler
            notifier.OnNotify -= MessagePrinter;

            Console.WriteLine("\nAfter unsubscribing MessagePrinter:");
            notifier.SendWelcome();   // Only the lambda prints

            // ----------------------------------------------------
            // 5. Event with custom EventArgs (optional)
            // ----------------------------------------------------
            var progressReporter = new ProgressReporter();
            progressReporter.ProgressChanged += ProgressHandler;
            progressReporter.Start();

            Console.WriteLine("\nPress any key to exit...");
            Console.ReadKey();
        }

        // --- Simple methods used by the delegate examples ----------------
        static void MessagePrinter(string msg)
        {
            Console.WriteLine($"[Printer] {msg}");
        }

        static void MessageLogger(string msg)
        {
            // In a real app this might write to a file or database.
            Console.WriteLine($"[Logger] {msg}");
        }

        // --- Event handler with custom EventArgs -------------------------
        static void ProgressHandler(object sender, ProgressEventArgs e)
        {
            Console.WriteLine($"Progress: {e.Percentage}% - {e.Status}");
        }
    }

    // ----------------------------------------------------
    // 6. A class that raises a custom event with EventArgs
    // ----------------------------------------------------
    public class ProgressReporter
    {
        // Define the delegate that matches the standard EventHandler<T>
        public event EventHandler<ProgressEventArgs> ProgressChanged;

        // Raise the event
        protected virtual void OnProgressChanged(ProgressEventArgs e)
        {
            ProgressChanged?.Invoke(this, e);
        }

        // Simulate some work
        public void Start()
        {
            for (int i = 0; i <= 100; i += 20)
            {
                System.Threading.Thread.Sleep(200); // simulate work
                OnProgressChanged(new ProgressEventArgs(i, $"Step {i / 20} completed"));
            }
        }
    }

    // Custom EventArgs for progress updates
    public class ProgressEventArgs : EventArgs
    {
        public int Percentage { get; }
        public string Status { get; }

        public ProgressEventArgs(int percentage, string status)
        {
            Percentage = percentage;
            Status = status;
        }
    }
}
```

### What this code shows

| Feature | How it’s illustrated |
|---------|---------------------|
| **Delegate declaration** | `public delegate void NotificationHandler(string message);` |
| **Single‑cast delegate** | `NotificationHandler single = MessagePrinter; single(...);` |
| **Multi‑cast delegate** | `multi += MessageLogger;` – both methods run when invoked. |
| **Event declaration** | `public event NotificationHandler OnNotify;` |
| **Event subscription** | `notifier.OnNotify += MessagePrinter;` and `+=` with a lambda. |
| **Event unsubscription** | `notifier.OnNotify -= MessagePrinter;` |
| **Raising an event** | `RaiseNotification(...)` inside the `Notifier` class. |
| **Custom event arguments** | `ProgressReporter` uses `EventHandler<ProgressEventArgs>` to send structured data. |

Run the program, and you’ll see the console output from the delegate calls, the event notifications, and the progress updates. This should give you a clear, practical example of both delegates and events in C#.
